from flask import Flask, request, jsonify, g
import sqlite3
import json

app = Flask(__name__)
DATABASE = 'bookmarks.db'


def get_db():
    """Get database connection"""
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db


def init_db():
    """Initialize database and create table if not exists"""
    db = get_db()
    db.execute('''
        CREATE TABLE IF NOT EXISTS bookmarks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            url TEXT NOT NULL,
            title TEXT NOT NULL,
            tags TEXT NOT NULL
        )
    ''')
    db.commit()


@app.before_request
def before_request():
    g.db = None


@app.teardown_appcontext
def close_db(error):
    """Close database connection"""
    db = g.pop('db', None)
    if db is not None:
        db.close()


@app.route('/bookmarks', methods=['GET'])
def list_bookmarks():
    """List all bookmarks or filter by tag"""
    tag = request.args.get('tag')
    db = get_db()

    if tag:
        cursor = db.execute(
            'SELECT * FROM bookmarks WHERE ? IN (SELECT value FROM json_each(tags))',
            (tag,)
        )
    else:
        cursor = db.execute('SELECT * FROM bookmarks')

    bookmarks = [dict(row) for row in cursor.fetchall()]
    return jsonify(bookmarks)


@app.route('/bookmarks', methods=['POST'])
def add_bookmark():
    """Add a new bookmark"""
    data = request.get_json()

    if not data or 'url' not in data or 'title' not in data:
        return jsonify({'error': 'Missing required fields: url, title'}), 400

    db = get_db()
    cursor = db.execute(
        'INSERT INTO bookmarks (url, title, tags) VALUES (?, ?, ?)',
        (data['url'], data['title'], json.dumps(data.get('tags', [])))
    )
    db.commit()

    bookmark_id = cursor.lastrowid
    return jsonify({
        'id': bookmark_id,
        'url': data['url'],
        'title': data['title'],
        'tags': data.get('tags', [])
    }), 201


@app.route('/bookmarks/<int:id>', methods=['GET'])
def get_bookmark(id):
    """Get a specific bookmark by ID"""
    db = get_db()
    cursor = db.execute('SELECT * FROM bookmarks WHERE id = ?', (id,))
    bookmark = cursor.fetchone()

    if bookmark is None:
        return jsonify({'error': 'Bookmark not found'}), 404

    return jsonify(dict(bookmark))


@app.route('/bookmarks/<int:id>', methods=['DELETE'])
def delete_bookmark(id):
    """Delete a bookmark by ID"""
    db = get_db()
    cursor = db.execute('SELECT * FROM bookmarks WHERE id = ?', (id,))
    bookmark = cursor.fetchone()

    if bookmark is None:
        return jsonify({'error': 'Bookmark not found'}), 404

    db.execute('DELETE FROM bookmarks WHERE id = ?', (id,))
    db.commit()

    return jsonify({'message': 'Bookmark deleted'}), 200


if __name__ == '__main__':
    init_db()
    app.run(debug=True)

